class Gradebook:
    def __init__(self) -> None:
        self._assignments = {}
        self._grades = {}

    def add_assignment(
        self, name: str, weight: float, kind: str = "homework"
    ) -> None:
        if name in self._assignments:
            raise ValueError(f"Assignment already exists: {name}")
        if kind not in ("homework", "quiz"):
            raise ValueError("kind must be 'homework' or 'quiz'")
        if weight < 0:
            raise ValueError("weight cannot be negative")
        self._assignments[name] = (weight, kind)

    def record(self, student: str, assignment: str, grade: float) -> None:
        if assignment not in self._assignments:
            raise KeyError(assignment)
        if not 2.0 <= grade <= 5.0:
            raise ValueError("grade must be between 2.0 and 5.0")
        self._grades.setdefault(student, {})[assignment] = grade

    def average(self, student: str) -> float:
        grades = self._grades.get(student, {})
        quizzes = [
            name
            for name, (_, kind) in self._assignments.items()
            if kind == "quiz"
        ]

        dropped = None
        if len(quizzes) > 1:
            dropped = min(quizzes, key=lambda name: grades.get(name, 2.0))

        total = 0.0
        total_weight = 0.0
        for name, (weight, _) in self._assignments.items():
            if name == dropped:
                continue
            total += grades.get(name, 2.0) * weight
            total_weight += weight

        return round(total / total_weight, 2) if total_weight else 0.0
